// 隔离共享候选：三个本人命令均经原守卫/完整历史，只有真实接受会替换原Office。
#include "political_head_handover_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
// 空账同样验证原作者首府归属，不能让遗漏管辖的目录在新局获得默认合法身份。
Status available(const WorldBundle& w){if(!w.catalog->political_head_handovers||!w.political_head_handovers||!w.catalog->political_successions||!w.political_successions||!w.politics_enabled()||!w.catalog->organization||!w.catalog->organization->enabled||!w.family_life_enabled()||!w.catalog->common)return common_failure("PoliticalHeadHandoverProfileRequired");for(const auto& row:w.catalog->political_head_handovers->policies.rows()){const auto* p=w.catalog->political_successions->policies.find(row.second.succession_policy_id);const auto* j=p?w.catalog->politics->jurisdictions.find(p->jurisdiction_id):nullptr;if(!p||!j||j->revision!=0||j->office_id!=p->leader_office_id||j->seat_place_id!=p->seat_place_id||j->political_organization_id!=p->organization_id||j->controlling_organization_id!=p->organization_id)return common_failure("PoliticalHeadHandoverOriginalSeatRequired",row.first);}return common_success();}
// 同命令名不能替代实际明细；接受还必须携同一次原Office变更来源。
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){if(!r.ok||!r.details)return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);return e&&valid_political_head_handover_effect(r.kind,*e)&&e->fact_ids==std::vector<StableId>{source}&&e->receipt_ids==(office.empty()?std::vector<StableId>{}:std::vector<StableId>{office});}
// 玩家本人身份不能代原共同生命、行动及舟上等守卫；两个NPC入口另在写前拒本命令。
Status player(const WorldBundle& w,const StableId& actor,const PoliticalHeadHandoverCommand& c){auto v=command_common_guard(w,actor,political_head_handover_command_kind(c));if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalHeadHandoverPlayerCommandRequired");}
}
PoliticalHeadHandoverWorldAccess::PoliticalHeadHandoverWorldAccess(const WorldBundle& w)
 :world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),
 occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),
 territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr},
 rules_{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_successions,*w.catalog->political_head_handovers,*w.political_head_handovers,w.family_death_read(),[this](const PoliticalSuccessionPolicy& p,Integer tick,const StableId& fact){return validate_political_head_handover_seat(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_head_handover_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);}},context_{rules_,actual_result}{}
Outcome<std::unique_ptr<PoliticalHeadHandoverWorldAccess>> PoliticalHeadHandoverWorldAccess::create(const WorldBundle& w){auto v=available(w);if(!v.ok)return {false,{},v.error};return {true,std::unique_ptr<PoliticalHeadHandoverWorldAccess>{new PoliticalHeadHandoverWorldAccess(w)},{}};}
// 原Organization、生命、Family/Born/Legacy与首职继位完整史先验后才检查本独立段。
Status validate_political_head_handover_world(const WorldBundle& w){auto v=validate_political_head_handover_layout(w.common,w.catalog->identity.module_versions,w.political_head_handovers?&*w.political_head_handovers:nullptr);if(!v.ok)return v;if(bool(w.catalog->political_head_handovers)!=w.political_head_handovers.has_value())return common_failure("PoliticalHeadHandoverProfileMismatch");if(!w.catalog->political_head_handovers)return common_success();auto read=PoliticalHeadHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return validate_political_head_handovers(read.value->context());}
Outcome<PoliticalHeadHandoverQuote> prepare_political_head_handover_world(const WorldBundle& w,const StableId& actor,const PoliticalHeadHandoverCommand& c){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalHeadHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return preview_political_head_handover_business(read.value->context(),actor,c);}
Outcome<PoliticsEffects> commit_political_head_handover_world(WorldBundle& w,const StableId& actor,const PoliticalHeadHandoverCommand& c,const PoliticalHeadHandoverQuote& q){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalHeadHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto r=apply_political_head_handover_business_in_candidate(w.common,w.organization,*w.political_head_handovers,read.value->context(),actor,c,q);if(!r.ok)return {false,{},r.error};return {true,{{},{r.value.source_fact_id},r.value.office_change_fact_id.empty()?std::vector<StableId>{}:std::vector<StableId>{r.value.office_change_fact_id}},{}};}
Outcome<BoundaryValue> query_political_head_handover_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalHeadHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return query_political_head_handovers(read.value->context(),place,cursor);}
Status bind_political_head_handover_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.catalog->political_head_handovers||!w.political_head_handovers||source.empty()||!is_political_head_handover_command(result.kind))return common_failure("PoliticalHeadHandoverNewSourceRequired");return bind_political_head_handover_player_result(w.common,*w.political_head_handovers,source,actor,request,result,actual_result);}
}
